originals=[[]]

o = int(input())
t = int(input())

if o != t:
    print("It's a mess!")
    exit()


x=0
for i in range(o):
    original = input()
    if (original == "NEXT"):
        x+=1
        originals.append([])
    else:
        originals[x].append(original)

x=0
for i in range(t):
    tested = input()
    if (tested == "NEXT"):
        x+=1
    else:
        if tested in originals[x]:
            originals[x].remove(tested)
        else:
            print("It's a mess!")
            exit()

print("Perfect Recipe" if not any(originals) else "It's a mess!")
